function topicMatch(pattern, key) {
  const p = pattern.split('.');
  const k = key.split('.');
  function rec(i, j) {
    if (i === p.length) return j === k.length;
    if (p[i] === '#') {
      for (let n = j; n <= k.length; n++) { if (rec(i + 1, n)) return true; }
      return false;
    }
    if (j === k.length) return false;
    if (p[i] === '*' || p[i] === k[j]) return rec(i + 1, j + 1);
    return false;
  }
  return rec(0, 0);
}
